class Solution {
  public String removeSubstring(String s, int k) {
    int n = s.length();
    char[] type = new char[n + 1];
    int[] count = new int[n + 1];
    int top = 0;
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      if (top > 0 && type[top - 1] == c) {
        count[top - 1]++;
      } else {
        type[top] = c;
        count[top++] = 1;
      }
      if (c == ')' && top >= 2 && count[top - 1] >= k && count[top - 2] >= k) {
        count[top - 1] -= k;
        count[top - 2] -= k;
        if (count[top - 1] == 0) top--;
        if (top > 0 && count[top - 1] == 0) top--;
      }
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < top; i++) for (int t = 0; t < count[i]; t++) sb.append(type[i]);
    return sb.toString();
  }
}
